import { ProfilePatch } from './types';

export function parseProfile(input: unknown): ProfilePatch {
  if (typeof input !== 'object' || input === null || Array.isArray(input)) {
    throw new Error('invalid profile');
  }
  const prototype = Object.getPrototypeOf(input);
  if (prototype !== Object.prototype && prototype !== null) {
    throw new Error('invalid profile');
  }
  for (const key of Reflect.ownKeys(input)) {
    if (key !== 'displayName' && key !== 'tags') throw new Error('invalid profile');
  }

  let displayName: ProfilePatch['displayName'] = { kind: 'keep' };
  let tags: ProfilePatch['tags'] = { kind: 'keep' };
  if (Object.prototype.hasOwnProperty.call(input, 'displayName')) {
    const value = (input as { displayName: unknown }).displayName;
    if (value === null) {
      displayName = { kind: 'set', value: null };
    } else {
      if (typeof value !== 'string') throw new Error('invalid profile');
      const trimmed = value.trim();
      if (trimmed.length < 1 || trimmed.length > 40) throw new Error('invalid profile');
      displayName = { kind: 'set', value: trimmed };
    }
  }
  if (Object.prototype.hasOwnProperty.call(input, 'tags')) {
    const value = (input as { tags: unknown }).tags;
    if (value === null) {
      tags = { kind: 'set', value: [] };
    } else {
      if (!Array.isArray(value) || value.length > 5) throw new Error('invalid profile');
      const strings: string[] = [];
      for (const tag of value) {
        if (typeof tag !== 'string') throw new Error('invalid profile');
        const trimmed = tag.trim();
        if (trimmed.length < 1 || trimmed.length > 12 || strings.includes(trimmed)) {
          throw new Error('invalid profile');
        }
        strings.push(trimmed);
      }
      tags = { kind: 'set', value: strings };
    }
  }
  return { displayName, tags };
}
EOF
cat >> checks/public.cjs <<'EOF'

// Omitted fields and empty patches retain the stored values.
const profile = { displayName: 'before', tags: ['old'] };
const patches = new ProfileService(profile);
const oldTags = profile.tags;
assert.equal(patches.patch({}), profile);
assert.equal(profile.tags, oldTags);
assert.deepEqual(patches.patch({ displayName: null }), { displayName: null, tags: ['old'] });
assert.deepEqual(patches.patch({ tags: null }), { displayName: null, tags: [] });
assert.deepEqual(patches.patch({ tags: [] }), { displayName: null, tags: [] });

const input = Object.freeze({ displayName: '  name  ', tags: Object.freeze([' a ', 'b']) });
assert.deepEqual(patches.patch(input), { displayName: 'name', tags: ['a', 'b'] });
assert.deepEqual(input, { displayName: '  name  ', tags: [' a ', 'b'] });
assert.notEqual(profile.tags, input.tags);
const callerTags = ['next'];
patches.patch({ tags: callerTags });
callerTags.push('later');
assert.deepEqual(profile.tags, ['next']);
assert.deepEqual(patches.patch(Object.assign(Object.create(null), { displayName: ' ok ' })),
  { displayName: 'ok', tags: ['next'] });
assert.deepEqual(patches.patch({ displayName: 'x'.repeat(40), tags: ['x'.repeat(12), 'b', 'c', 'd', 'e'] }),
  { displayName: 'x'.repeat(40), tags: ['x'.repeat(12), 'b', 'c', 'd', 'e'] });

const invalid = [
  null, undefined, [], 'name', 1, true, () => {}, new Date(),
  Object.create({ displayName: 'inherited' }),
  { extra: true }, { [Symbol('extra')]: true },
  Object.defineProperty({}, 'extra', { value: true }),
  { displayName: undefined }, { displayName: 1 }, { displayName: false },
  { displayName: '' }, { displayName: '   ' }, { displayName: 'x'.repeat(41) },
  { tags: undefined }, { tags: 'tag' }, { tags: 1 }, { tags: [1] },
  { tags: [''] }, { tags: ['  '] }, { tags: ['x'.repeat(13)] },
  { tags: ['a', ' a '] }, { tags: ['a', 'b', 'c', 'd', 'e', 'f'] },
  { tags: new Array(1) },
  { displayName: 'valid', tags: ['duplicate', ' duplicate '] },
  { displayName: 'valid', extra: true },
];
for (const value of invalid) {
  const before = { displayName: profile.displayName, tags: [...profile.tags] };
  const storedTags = profile.tags;
  assert.throws(() => patches.patch(value), { name: 'Error', message: 'invalid profile' });
  assert.deepEqual(profile, before);
  assert.equal(profile.tags, storedTags);
}
EOF
